#define main legacy_main
#include "scatter-cuda/main.cu"
#undef main
#include <vector>
static std::vector<double>allvalues;static double total_time;static bool allcorrect;
template<class T,ReductionType OP>void studycase(int n,int repeat){int outn=n/2;std::vector<T>src(n),init(outn,Reducer<T,OP>::init()),expected=init,out(outn);std::vector<int64_t>idx(n);for(int i=0;i<n;i++){idx[i]=(int64_t(i)*17+3)%outn;src[i]=i%3==0?-1:1;Reducer<T,OP>::update(expected[idx[i]],src[i]);}T *ds,*dy;int64_t*di;cudaMalloc(&ds,n*sizeof(T));cudaMalloc(&dy,outn*sizeof(T));cudaMalloc(&di,n*8);cudaMemcpy(ds,src.data(),n*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(di,idx.data(),n*8,cudaMemcpyHostToDevice);int64_t sizes[MAX_TENSORINFO_DIMS]={n},strides[MAX_TENSORINFO_DIMS]={1};TensorInfo<int64_t,int64_t>info(di,1,sizes,strides);
cudaMemcpy(dy,init.data(),outn*sizeof(T),cudaMemcpyHostToDevice);scatter_kernel<T,OP><<<(n+255)/256,256>>>(ds,info,dy,n,1,outn,n);if(cudaDeviceSynchronize()!=cudaSuccess)exit(2);double t=0.;for(int j=0;j<repeat;j++){cudaMemcpy(dy,init.data(),outn*sizeof(T),cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();scatter_kernel<T,OP><<<(n+255)/256,256>>>(ds,info,dy,n,1,outn,n);if(cudaDeviceSynchronize()!=cudaSuccess)exit(2);t+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}total_time+=t/repeat;cudaMemcpy(out.data(),dy,outn*sizeof(T),cudaMemcpyDeviceToHost);for(int i=0;i<outn;i++){allcorrect &=out[i]==expected[i]&&std::isfinite(double(out[i]));allvalues.push_back(double(out[i]));}cudaFree(ds);cudaFree(dy);cudaFree(di);}
template<class T>void typecases(int n,int repeat){studycase<T,MUL>(n,repeat);studycase<T,DIV>(n,repeat);studycase<T,SUM>(n,repeat);studycase<T,MIN>(n,repeat);studycase<T,MAX>(n,repeat);}
int main(){int n=4096,repeat=10;for(int trial=1;trial<=5;trial++){allvalues.clear();total_time=0.;allcorrect=true;typecases<int32_t>(n,repeat);typecases<int64_t>(n,repeat);typecases<float>(n,repeat);typecases<double>(n,repeat);char file[32];snprintf(file,sizeof(file),"trial_%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(allvalues.data(),8,allvalues.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"timing_region\":\"sum_twenty_individually_synchronized_kernel_means_excluding_reset\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total_time,allcorrect?"true":"false",allvalues.size(),allcorrect?0:1,repeat,file,allvalues.size());if(!allcorrect)return 1;}}
